    "question": "Cas clinique — Monsieur MS, âgé de 75 ans, vit avec sa femme ; il a une cataracte, une hypertension artérielle et un diabète de type 2 traité à base de metformine 850 mg trois comprimés/jour et un sulfamide type gliclazide deux comprimés à midi, un inhibiteur de l’enzyme de conversion pour son HTA ; sa femme fait son ménage seule ainsi que ses courses, comme elle le prend en charge (toilette, alimentation, hygiène) ; les fonctions mentales sont non altérées. Depuis quelques jours le patient a présenté une anorexie, une fièvre suivie d’une toux productive : son bilan biologique (FNS, débit de filtration glomérulaire par MDRD est normal, son HbA1c est à 7,3 %). Son médecin traitant a introduit une antibiothérapie et un fluidifiant pulmonaire. Selon vous la perte d’autonomie chez ce patient est dû à :",
    "propositions": {
      "A": "Trouble cognitif.",
      "B": "Anorexie.",
      "C": "Dénutrition.",
      "D": "Diabète type 2"
    },
    "question_fr": "Cas clinique — Monsieur MS, âgé de 75 ans, vit avec sa femme ; il a une cataracte, une hypertension artérielle et un diabète de type 2 traité à base de metformine 850 mg trois comprimés/jour et un sulfamide type gliclazide deux comprimés à midi, un inhibiteur de l’enzyme de conversion pour son HTA ; sa femme fait son ménage seule ainsi que ses courses, comme elle le prend en charge (toilette, alimentation, hygiène) ; les fonctions mentales sont non altérées. Depuis quelques jours le patient a présenté une anorexie, une fièvre suivie d’une toux productive : son bilan biologique (FNS, débit de filtration glomérulaire par MDRD est normal, son HbA1c est à 7,3 %). Son médecin traitant a introduit une antibiothérapie et un fluidifiant pulmonaire. Selon vous la perte d’autonomie chez ce patient est dû à :",
