    "question_fr": "Cas clinique — Cas clinique 1 — Mme S. Y., 86 ans, vit avec son petit-fils depuis le décès de son mari il y a 4 ans. Antécédents : HTA depuis plus de 30 ans, ACFA ; maladie d'Alzheimer depuis 4 ans évolutive ; arthrose généralisée générant des douleurs à la mobilisation ; hypoacousie. Habitudes de vie : aide pour l'alimentation avec plusieurs épisodes de fausses routes ; aide totale pour la toilette ; réduction remarquable de l'activité physique et psychique ; trouble de mémoire remarquable ; alitement progressif depuis plus de 3 mois avec change complet jour et nuit ; position fœtale ; réduction de la quantité d'alimentation. Épisode actuel : ramenée par son petit-fils pour détresse respiratoire aiguë et apparition récente d'œdème du membre inférieur droit et de lésions au niveau sacré, à type d'ulcération profonde. Poids 45 kg, taille 1,65 m. Traitement : Aricept cp 10 mg soir, Lyrica 50 mg cp 3 fois/j, Cordarone, Amlor, Aspégic. La pneumopathie liée au décubitus est secondaire aux mécanismes suivants :",
